import { SPINNERS } from "./loading-dev/spinners";
import type { SpinnerName } from "./loading-dev/motion";
import type { SpinnerProps } from "./loading-dev/types";

/** Loading indicators adapted from loading-dev, MIT © 2026 Jakub Krehel.
 * See loading-dev/LICENSE.md for the complete license.
 */
export type LoadingIndicatorVariant = SpinnerName;
export interface LoadingIndicatorProps extends SpinnerProps {
  variant?: LoadingIndicatorVariant;
  label?: string;
  decorative?: boolean;
}

export function LoadingIndicator({ variant = "atom", label = "Loading", decorative = false, ...props }: LoadingIndicatorProps) {
  const Indicator = SPINNERS[variant];
  return <span role={decorative ? undefined : "status"} aria-label={decorative ? undefined : label} aria-hidden={decorative || undefined} style={{ display: "inline-flex", verticalAlign: "middle" }}><Indicator {...props} /></span>;
}

import { type CapProps, linecap } from "./cap";
import { type EasingProps, rotationCss, spinClass } from "./easing";
import { SpinnerStyle, spinnerRoot } from "./frame";
import type { SpinnerProps } from "./types";

export interface ArcProps extends SpinnerProps, EasingProps, CapProps {}

const css = `
${rotationCss("arc")}
`;

export function Arc({ cap, easing, ...rest }: ArcProps) {
  return (
    <>
      <SpinnerStyle name="arc">{css}</SpinnerStyle>
      <svg
        {...spinnerRoot("arc", rest)}
        fill="none"
        role="presentation"
        viewBox="0 0 24 24"
      >
        <circle
          className={spinClass("arc", easing)}
          cx="12"
          cy="12"
          r="10"
          stroke="currentColor"
          strokeDasharray="18 44.8"
          strokeLinecap={linecap(cap)}
          strokeWidth="2.5"
        />
      </svg>
    </>
  );
}

import { type EasingProps, rotationCss, spinClass } from "./easing";
import { cssVars, SpinnerStyle, spinnerRoot, step } from "./frame";
import { SIZE, stagger } from "./motion";
import type { SpinnerProps } from "./types";

export interface AtomProps extends SpinnerProps, EasingProps {}

const ORBITS = Array.from({ length: 3 }, (_, index) => index);

const TILT = 180 / ORBITS.length;

const STROKE = `calc(${SIZE} * 0.055)`;

const INNER_STROKE = `calc(${SIZE} * 0.045)`;

const css = `
.ld-atom {
  position: relative;
}

.ld-atom-shell {
  position: absolute;
  inset: 0;
  box-sizing: border-box;
  border: ${STROKE} solid currentColor;
  border-radius: 9999px;
}

.ld-atom-orbit {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  transform: rotate(var(--ld-atom-tilt)) rotateX(90deg);
}

.ld-atom-ring {
  position: absolute;
  inset: 0;
  box-sizing: border-box;
  border: ${INNER_STROKE} solid currentColor;
  border-radius: 9999px;
  transform: rotateX(90deg);
}

${rotationCss("atom")}

.ld-atom-spin {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  animation-delay: ${stagger("atom", ORBITS.length)};
}

@media (prefers-reduced-motion: reduce) {
  .ld-atom-spin {
    transform: rotate(${TILT}deg);
  }
}
`;

export function Atom({ easing, ...rest }: AtomProps) {
  return (
    <>
      <SpinnerStyle name="atom">{css}</SpinnerStyle>
      <span {...spinnerRoot("atom", rest)}>
        <span className="ld-atom-shell" />
        {ORBITS.map((index) => (
          <span
            className="ld-atom-orbit"
            key={index}
            style={cssVars({ "--ld-atom-tilt": `${index * TILT}deg` })}
          >
            <span className={spinClass("atom", easing)} style={step(index)}>
              <span className="ld-atom-ring" />
            </span>
          </span>
        ))}
      </span>
    </>
  );
}

import { SpinnerStyle, spinnerRoot, step } from "./frame";
import { animation, SIZE, stagger } from "./motion";
import type { SpinnerProps } from "./types";

export type BlocksSweep = "columns" | "diagonal" | "rows";

export const DEFAULT_BLOCKS_SWEEP: BlocksSweep = "diagonal";

export interface BlocksProps extends SpinnerProps {
  sweep?: BlocksSweep;
}

const SIDE = 3;

interface Cell {
  col: number;
  row: number;
}

const CELLS: Cell[] = Array.from({ length: SIDE * SIDE }, (_, index) => ({
  col: index % SIDE,
  row: Math.floor(index / SIDE),
}));

const SWEEPS: Record<
  BlocksSweep,
  { count: number; place: (cell: Cell) => number }
> = {
  columns: { count: SIDE, place: ({ col }) => col },
  diagonal: { count: SIDE * 2 - 1, place: ({ col, row }) => row + col },
  rows: { count: SIDE, place: ({ row }) => row },
};

const css = `
.ld-blocks {
  display: grid;
  grid-template-columns: repeat(${SIDE}, 1fr);
  grid-template-rows: repeat(${SIDE}, 1fr);
  gap: calc(${SIZE} * 0.1);
}

.ld-blocks-cell {
  background: currentColor;
  border-radius: calc(${SIZE} * 0.0625);
  ${animation("blocks", "ld-blocks-sweep", "ease-in-out")}
}
${Object.entries(SWEEPS)
  .map(
    ([sweep, { count }]) => `
.ld-blocks-cell-${sweep} {
  animation-delay: ${stagger("blocks", count)};
}
`
  )
  .join("")}
@keyframes ld-blocks-sweep {
  0%,
  70%,
  100% {
    transform: scale(1);
  }
  35% {
    transform: scale(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .ld-blocks-cell {
    transform: scale(0.8);
  }
}
`;

export function Blocks({ sweep = DEFAULT_BLOCKS_SWEEP, ...rest }: BlocksProps) {
  const { place } = SWEEPS[sweep];
  return (
    <>
      <SpinnerStyle name="blocks">{css}</SpinnerStyle>
      <span {...spinnerRoot("blocks", rest)}>
        {CELLS.map((cell) => (
          <span
            className={`ld-blocks-cell ld-blocks-cell-${sweep}`}
            key={`${cell.col}-${cell.row}`}
            style={step(place(cell))}
          />
        ))}
      </span>
    </>
  );
}

import { SpinnerStyle, spinnerRoot, step } from "./frame";
import { animation, SIZE, stagger } from "./motion";
import type { SpinnerProps } from "./types";

const DOTS = Array.from({ length: 3 }, (_, index) => index);

const css = `
