import type { CSSProperties } from "react";
import {
  DEFAULT_SIZE,
  DURATION_VAR,
  PLAY_STATE_VAR,
  SIZE,
  SIZE_VAR,
  type SpinnerName,
  STEP_VAR,
} from "./motion";
import type { SpinnerProps } from "./types";

export function SpinnerStyle({
  children,
  name,
}: {
  children: string;
  name: SpinnerName;
}) {
  return (
    <style href={`ld-${name}`} precedence="loading-dev">
      {`
.ld-${name} {
  display: inline-block;
  width: ${SIZE};
  height: ${SIZE};
}
:where(.ld-${name} span) { display: block; }
${children}
@media (prefers-reduced-motion: reduce) {
  .ld-${name},
  .ld-${name} * {
    animation: none;
  }
}
`}
    </style>
  );
}

export function cssVars(
  vars: CSSProperties & Record<`--ld-${string}`, number | string>
): CSSProperties {
  return vars;
}

export function step(index: number): CSSProperties {
  return cssVars({ [STEP_VAR]: index });
}

export function spinnerRoot(
  name: SpinnerName,
  { className, color, duration, playState, size = DEFAULT_SIZE }: SpinnerProps
) {
  return {
    "aria-hidden": true,
    className: [`ld-${name}`, className].filter(Boolean).join(" "),
    style: cssVars({
      [SIZE_VAR]: `${size}px`,
      ...(color === undefined ? null : { color }),
      ...(duration === undefined ? null : { [DURATION_VAR]: `${duration}ms` }),
      ...(playState === undefined ? null : { [PLAY_STATE_VAR]: playState }),
    }),
  };
}

import { cssVars, SpinnerStyle, spinnerRoot } from "./frame";
import { animation, SIZE } from "./motion";
import type { SpinnerProps } from "./types";

const BLOCKS = [
  { x: 1, y: 1 },
  { x: -1, y: 1 },
  { x: 1, y: -1 },
  { x: -1, y: -1 },
];

const GAP = 24;

const GAP_IN = 8;

const BLOCK = (100 - GAP) / 2;

const PULL = `${(((GAP - GAP_IN) / 2 / BLOCK) * 100).toFixed(1)}%`;

const css = `
.ld-gather-group {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: ${GAP}%;
  width: 100%;
  height: 100%;
  ${animation("gather", "ld-gather-turn", "ease-in-out")}
}

.ld-gather-block {
  background: currentColor;
  border-radius: calc(${SIZE} * 0.14);
  ${animation("gather", "ld-gather-pull", "ease-in-out")}
}

@keyframes ld-gather-pull {
  0%,
  100% {
    transform: translate(0, 0);
  }
  30%,
  60% {
    transform: translate(
      calc(var(--ld-gather-x) * ${PULL}),
      calc(var(--ld-gather-y) * ${PULL})
    );
  }
}

@keyframes ld-gather-turn {
  0%,
  30% {
    transform: rotate(0);
  }
  60%,
  100% {
    transform: rotate(90deg);
  }
}
`;

export function Gather(props: SpinnerProps) {
  return (
    <>
      <SpinnerStyle name="gather">{css}</SpinnerStyle>
      <span {...spinnerRoot("gather", props)}>
        <span className="ld-gather-group">
          {BLOCKS.map(({ x, y }) => (
            <span
              className="ld-gather-block"
              key={`${x}${y}`}
              style={cssVars({ "--ld-gather-x": x, "--ld-gather-y": y })}
            />
          ))}
        </span>
      </span>
    </>
  );
}

