export interface TraceProps extends SpinnerProps, EasingProps, CapProps {}

const VIEW = 20;

const SIDE = 17.5;

const RADIUS = 4;

const PERIMETER = 4 * (SIDE - 2 * RADIUS) + 2 * Math.PI * RADIUS;

const DASH = 16;

const RECT = {
  height: SIDE,
  rx: RADIUS,
  width: SIDE,
  x: (VIEW - SIDE) / 2,
  y: (VIEW - SIDE) / 2,
};

const css = `
${rotationCss(
  "trace",
  `to {
    stroke-dashoffset: ${-PERIMETER};
  }`
)}
`;

export function Trace({ cap, easing, ...rest }: TraceProps) {
  return (
    <>
      <SpinnerStyle name="trace">{css}</SpinnerStyle>
      <svg
        {...spinnerRoot("trace", rest)}
        fill="none"
        role="presentation"
        stroke="currentColor"
        strokeWidth="2.5"
        viewBox={`0 0 ${VIEW} ${VIEW}`}
      >
        <rect {...RECT} opacity="0.2" />
        <rect
          {...RECT}
          className={spinClass("trace", easing)}
          strokeDasharray={`${DASH} ${PERIMETER - DASH}`}
          strokeLinecap={linecap(cap)}
        />
      </svg>
    </>
  );
}

export interface SpinnerProps {
  className?: string;
  color?: string;
  duration?: number;
  playState?: "paused" | "running";
  size?: number;
}

import { SpinnerStyle, spinnerRoot, step } from "./frame";
import { animation, SIZE, STEP_VAR, stagger } from "./motion";
import type { SpinnerProps } from "./types";

export type WaveOrigin = "bottom" | "center";

export const DEFAULT_WAVE_ORIGIN: WaveOrigin = "center";

export interface WaveProps extends SpinnerProps {
  origin?: WaveOrigin;
}

const BARS = Array.from({ length: 5 }, (_, index) => index);

const css = `
.ld-wave {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.ld-wave-bar {
  width: calc(${SIZE} * 0.12);
  height: 100%;
  background: currentColor;
  border-radius: 9999px;
  ${animation("wave", "ld-wave-rise", "ease-in-out")}
  animation-delay: ${stagger("wave", BARS.length)};
}

.ld-wave-bar-bottom {
  align-self: flex-end;
}

@keyframes ld-wave-rise {
  0%,
  100% {
    height: 30%;
  }
  50% {
    height: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ld-wave-bar {
    height: calc((0.4 + var(${STEP_VAR}) * 0.15) * 100%);
  }
}
`;

export function Wave({ origin = DEFAULT_WAVE_ORIGIN, ...rest }: WaveProps) {
  return (
    <>
      <SpinnerStyle name="wave">{css}</SpinnerStyle>
      <span {...spinnerRoot("wave", rest)}>
        {BARS.map((index) => (
          <span
            className={`ld-wave-bar ld-wave-bar-${origin}`}
            key={index}
            style={step(index)}
          />
        ))}
      </span>
    </>
  );
}
